/** Real current policy/store/controller; network/native/UI inputs are explicit. */
public final class IpTimeZoneHost {
  static Path root;static int serial;static final List<String> checks=new ArrayList<>();
  interface Action {void run()throws Exception;}
  static void check(String name,boolean pass){if(!pass)throw new AssertionError(name);checks.add(name);}
  static void rejects(String name,Action work)throws Exception{boolean rejected=false;try{work.run();}catch(Exception expected){rejected=true;}check(name,rejected);}
  static final String A=new String(new char[64]).replace('\0','a'),B=new String(new char[64]).replace('\0','b');
  static ChatSession session()throws Exception{ChatSession s=new ChatSession(new TestContext(root.resolve("case-"+(++serial)),new EnvironmentSpec.Identity(2,4,GeckoTimeZoneHost.ID)));s.timeZone.load();s.pump();return s;}
  static String envelope(String token,String route,String ip,String zone){return J.obj("schema",1,"status","observed","requestToken",token,"routeStamp",route,"source",GeckoIpTimeZonePolicy.SOURCE,"body",J.obj("success",true,"ip",ip,"timezone",J.obj("id",zone)).toString()).toString();}
  static GeckoIpTimeZonePolicy.Observation observation()throws Exception{return GeckoIpTimeZonePolicy.parse(envelope(A,B,"8.8.8.8","America/New_York"),A,B,12345);}
  static List<Boolean> prepare(ChatSession s,Access n){List<Boolean> done=new ArrayList<>();s.timeZone.prepare(n.nativeSession,n.sid,n.epoch,n,done::add);return done;}
  static void resolve(ChatSession s,Access n,String zone){n.queryOk.accept(envelope(n.queryToken,n.route,"8.8.8.8",zone));s.handler.drain();}
  static void bootstrap(ChatSession s,Access n){n.readOk.accept(n.ack(n.readToken,"",n.context));s.pump();}
  static void accept(ChatSession s,Access n){bootstrap(s,n);n.applyOk.accept(n.ack(n.applyToken,n.zone,n.context));s.pump();}
  static boolean matched(ChatSession s,Access n){return s.timeZone.status(n.nativeSession,n.epoch).optBoolean("ipMatched");}
  static void parser()throws Exception{
    GeckoIpTimeZonePolicy.Observation good=observation();check("Exact fixed-service public-IP/IANA response is parsed without a country guess",good.ip.equals("8.8.8.8")&&good.zoneId.equals("America/New_York")&&good.routeStamp.equals(B));
    check("Historical metadata roundtrip does not provide a current native ticket",GeckoIpTimeZonePolicy.historical(good.json()).effective().equals(GeckoTimeZoneSpec.of("America/New_York")));
    for(String ip:new String[]{"1.1.1.1","8.8.4.4","2606:4700:4700::1111"})check("Public literal accepted: "+ip,!GeckoIpTimeZonePolicy.publicIp(ip).isEmpty());
    for(String ip:new String[]{"localhost","example.com",""," 8.8.8.8","8.8.8.8 ","08.8.8.8","127.1","0x08080808","8.8.8.999","0.0.0.0","127.0.0.1","10.2.3.4","192.168.1.1","172.16.1.2","169.254.1.1","100.64.0.1","192.0.2.1","198.51.100.1","203.0.113.1","198.18.0.1","224.0.0.1","::1","::","fe80::1","fc00::1","2001:db8::1","::ffff:127.0.0.1","2606:4700::1%1"})rejects("Invalid/nonpublic literal cannot become an exit observation: "+ip,()->GeckoIpTimeZonePolicy.publicIp(ip));
    JSONObject valid=new JSONObject(envelope(A,B,"8.8.8.8","Asia/Kathmandu"));
    for(Object[] change:new Object[][]{{"schema",true},{"schema",2},{"status","failed"},{"requestToken",B},{"routeStamp",A},{"source","http://ipwho.is/"},{"body",false},{"account","not-allowed"}}){JSONObject bad=new JSONObject(valid.toString());bad.put((String)change[0],change[1]);rejects("Foreign/malformed envelope rejected: "+change[0],()->GeckoIpTimeZonePolicy.parse(bad.toString(),A,B,5));}
    for(JSONObject body:new JSONObject[]{J.obj("success",false,"ip","8.8.8.8","timezone",J.obj("id","UTC")),J.obj("success",true,"ip",8,"timezone",J.obj("id","UTC")),J.obj("success",true,"ip","8.8.8.8","timezone",J.obj("id","UTC+08:00")),J.obj("success",true,"ip","8.8.8.8","timezone",J.obj("id","")),J.obj("success",true,"ip","8.8.8.8","timezone",J.obj("id","Missing/City")),J.obj("success",true,"ip","8.8.8.8","country_code","US"),J.obj("success",true,"ip","8.8.8.8","timezone",J.obj("id","UTC","offset",0))}){JSONObject bad=new JSONObject(valid.toString());bad.put("body",body.toString());rejects("Missing, guessed, fixed-offset or overfull timezone payload rejected",()->GeckoIpTimeZonePolicy.parse(bad.toString(),A,B,5));}
    String duplicate="{\"schema\":1,"+valid.toString().substring(1);rejects("Duplicate envelope keys rejected by the strict parser",()->GeckoIpTimeZonePolicy.parse(duplicate,A,B,1));
    JSONObject badBody=new JSONObject(valid.toString());badBody.put("body","{\"success\":true,\"success\":true,\"ip\":\"8.8.8.8\",\"timezone\":{\"id\":\"UTC\"}}");rejects("Duplicate service keys rejected",()->GeckoIpTimeZonePolicy.parse(badBody.toString(),A,B,1));
    rejects("Oversized response rejected before native work",()->GeckoIpTimeZonePolicy.parse(new String(new char[8193]),A,B,1));
  }
  static void specsAndStorage()throws Exception{
    ChatSession s=session();GeckoTimeZoneStore.State fresh=s.timeZone.cached;
    check("A genuinely missing environment sidecar defaults to explicit IP mode",fresh.revision==1&&fresh.spec.followsIp()&&!fresh.spec.followsSystem());
    rejects("Unresolved IP policy cannot silently use the phone offset",()->fresh.spec.offsetAt(java.time.Instant.EPOCH));
    check("IP and manual system remain distinct even with an empty zoneId",!GeckoTimeZoneSpec.automatic().equals(GeckoTimeZoneSpec.system())&&GeckoTimeZoneSpec.from(fresh.spec.json()).followsIp());
    rejects("IP policy cannot mint a native ticket without an observed IANA zone",()->GeckoTimeZoneStore.activate(s.context,fresh.identity,fresh.revision,GeckoTimeZoneHost.binding()));
    GeckoTimeZoneStore.Ticket ip=GeckoTimeZoneStore.activateIp(s.context,fresh.identity,fresh.revision,GeckoTimeZoneHost.binding(),observation());
    JSONObject receipt=GeckoTimeZoneStore.record(s.context,ip,GeckoTimeZoneHost.ack(ip,ip.effective).toString());
    check("IP receipt persists effective IANA and route-bound observation separately from desired mode",receipt.getInt("schema")==2&&receipt.getString("effectiveZoneId").equals("America/New_York")&&receipt.getJSONObject("ipObservation").getString("routeStamp").equals(B)&&GeckoTimeZoneStore.load(s.context).spec.followsIp());
    JSONObject wrong=GeckoTimeZoneHost.ack(ip,GeckoTimeZoneSpec.of("UTC"));rejects("Desired IP mode does not permit a mismatched native effective zone",()->GeckoTimeZoneStore.record(s.context,ip,wrong.toString()));
    GeckoTimeZoneStore.State system=GeckoTimeZoneStore.save(s.context,fresh.identity,1,GeckoTimeZoneSpec.system());check("An explicit manual system choice is a new CAS revision",system.revision==2&&GeckoTimeZoneStore.load(s.context).spec.followsSystem());
    rejects("Old IP receipt cannot satisfy a later manual choice",()->GeckoTimeZoneStore.record(s.context,ip,GeckoTimeZoneHost.ack(ip,ip.effective).toString()));
    rejects("Manual policy rejects an unsolicited IP observation ticket",()->GeckoTimeZoneStore.activateIp(s.context,system.identity,system.revision,GeckoTimeZoneHost.binding(),observation()));
    ChatSession legacy=session();JSONObject stored=GeckoTimeZoneHost.rawObject(legacy.context);stored.put("spec",J.obj("schema",1,"engine","gecko","zoneId",""));GeckoTimeZoneHost.rawWrite(legacy.context,stored.toString().getBytes(StandardCharsets.UTF_8));byte[] before=GeckoTimeZoneHost.raw(legacy.context);
    check("Strict schema1 migration preserves an old explicit or ambiguous system choice",GeckoTimeZoneStore.load(legacy.context).spec.followsSystem()&&Arrays.equals(before,GeckoTimeZoneHost.raw(legacy.context)));
    stored.put("spec",J.obj("schema",1,"engine","gecko","zoneId","Asia/Kathmandu"));GeckoTimeZoneHost.rawWrite(legacy.context,stored.toString().getBytes(StandardCharsets.UTF_8));check("Schema1 named choice remains manual IANA",GeckoTimeZoneStore.load(legacy.context).spec.equals(GeckoTimeZoneSpec.of("Asia/Kathmandu")));
    legacy.context.catalog.current=new EnvironmentSpec.Identity(2,5,GeckoTimeZoneHost.ID);check("Generation reset keeps explicit manual choice and clears historical native proof",GeckoTimeZoneStore.load(legacy.context).spec.zoneId.equals("Asia/Kathmandu")&&GeckoTimeZoneHost.rawObject(legacy.context).getJSONObject("receipt").length()==0);
    legacy.context.catalog.current=new EnvironmentSpec.Identity(2,0,GeckoTimeZoneHost.OTHER);check("A reused UUID slot receives the new IP default rather than its previous owner's manual zone",GeckoTimeZoneStore.load(legacy.context).spec.followsIp());
    for(JSONObject invalid:new JSONObject[]{J.obj("schema",2,"engine","gecko","zoneId","UTC"),J.obj("schema",3,"engine","gecko","mode","ip","zoneId",""),J.obj("schema",2,"engine","gecko","mode","ip","zoneId","UTC"),J.obj("schema",2,"engine","gecko","mode","system","zoneId","UTC"),J.obj("schema",2,"engine","gecko","mode","iana","zoneId","")})rejects("Mixed/unknown desired schema rejected",()->GeckoTimeZoneSpec.from(invalid));
  }
  static void sequenceAndRoute()throws Exception{
    ChatSession s=session();Access n=new Access(s.web.current);List<Boolean> done=prepare(s,n);
    check("Default IP preparation resolves exit before any native read or apply",n.queries==1&&n.reads==0&&n.applies==0&&done.isEmpty()&&!matched(s,n));
    resolve(s,n,"America/New_York");check("A valid route observation alone cannot permit first navigation",n.reads==1&&n.applies==0&&done.isEmpty()&&!s.timeZone.allowed(n.nativeSession,n.epoch));
    bootstrap(s,n);check("Native apply receives resolved IANA rather than empty desired IP zone",n.zone.equals("America/New_York")&&n.applies==1&&done.isEmpty());
    n.applyOk.accept(n.ack(n.applyToken,n.zone,n.context));s.handler.drain();check("Native ACK still awaits actual durable writer publication",done.isEmpty()&&!matched(s,n));s.environmentIo.drain();check("Writer alone cannot promote IP match before UI ownership check",done.isEmpty());s.handler.drain();
    check("First navigation is permitted only after current route observation and exact durable native ACK",done.equals(Arrays.asList(true))&&matched(s,n)&&s.timeZone.allowed(n.nativeSession,n.epoch));
    JSONObject state=s.timeZone.status(n.nativeSession,n.epoch);check("IP matching remains separate from page and all-worker effect",state.getString("effectiveZone").equals("America/New_York")&&state.getString("observedIp").equals("8.8.8.8")&&!state.getBoolean("pageObservationVerified")&&!state.getBoolean("workerCoverageVerified")&&!state.getBoolean("serviceWorkerCoverageVerified"));
    String old=s.timeZone.auditStamp();n.route=B;check("Route change immediately invalidates an old match even before a lifecycle notification",!matched(s,n)&&!s.timeZone.allowed(n.nativeSession,n.epoch));s.timeZone.ipRouteChanged();check("Route notification retires old audit proof while preserving the visible DOM",!old.equals(s.timeZone.auditStamp())&&s.web.reloads==0);
    List<Boolean> replacement=prepare(s,n);check("New route must perform its own lookup and cannot reuse old-route metadata",n.queries==2&&replacement.isEmpty());resolve(s,n,"Asia/Kathmandu");accept(s,n);check("New route may open only under its newly observed IANA zone",replacement.equals(Arrays.asList(true))&&matched(s,n)&&n.zone.equals("Asia/Kathmandu"));
    Access coop=new Access(n.nativeSession);coop.route=B;coop.context="7";List<Boolean> renewed=new ArrayList<>();s.timeZone.revalidate(coop.nativeSession,coop.sid,coop.epoch,coop,renewed::add);
    check("COOP same-route context renewal reuses only route metadata, not native confirmation",coop.queries==0&&coop.reads==1&&renewed.isEmpty()&&!matched(s,coop));accept(s,coop);check("COOP context receives fresh exact ticket without reloading or querying another exit",renewed.equals(Arrays.asList(true))&&matched(s,coop)&&s.web.reloads==0&&GeckoTimeZoneHost.rawObject(s.context).getJSONObject("receipt").getJSONObject("binding").getString("contextId").equals("7"));
  }
  static void failures()throws Exception{
    ChatSession s=session();Access n=new Access(s.web.current);List<Boolean> done=prepare(s,n);Consumer<String> late=n.queryOk;String token=n.queryToken;
    s.handler.advance(7999);s.pump();check("Lookup remains pending before its own eight-second bound",done.isEmpty()&&n.reads==0);s.handler.advance(1);s.pump();check("Failed IP lookup cannot silently fall back to system or permit navigation",done.equals(Arrays.asList(false))&&!matched(s,n)&&n.reads==0);late.accept(envelope(token,A,"8.8.8.8","UTC"));s.pump();check("Late lookup result cannot revive a timed-out operation",n.reads==0&&!matched(s,n));
    for(String invalid:new String[]{"token","route","source","body","live"}){ChatSession x=session();Access a=new Access(x.web.current);List<Boolean> out=prepare(x,a);JSONObject raw=new JSONObject(envelope(a.queryToken,a.route,"8.8.8.8","UTC"));if(invalid.equals("token"))raw.put("requestToken",B);if(invalid.equals("route"))raw.put("routeStamp",B);if(invalid.equals("source"))raw.put("source","https://other.example/");if(invalid.equals("body"))raw.put("body","{}");if(invalid.equals("live"))a.live=false;a.queryOk.accept(raw.toString());x.pump();check("Foreign or stale IP lookup never reaches native apply: "+invalid,a.reads==0&&a.applies==0&&!matched(x,a));}
    s=session();n=new Access(s.web.current);done=prepare(s,n);Consumer<String> old=n.queryOk;token=n.queryToken;List<String> saved=new ArrayList<>();s.timeZone.saveConfirmed(s.timeZone.cached,GeckoTimeZoneSpec.system(),()->true,saved::add);s.pump();old.accept(envelope(token,A,"8.8.8.8","UTC"));s.pump();check("A late automatic result cannot replace a saved manual system intent",s.timeZone.cached.spec.followsSystem()&&n.reads==0&&done.equals(Arrays.asList(false))&&saved.equals(Arrays.asList("")));
    Access manual=new Access(s.web.current);List<Boolean> manualDone=prepare(s,manual);check("Manual system bypasses IP lookup without being labeled matched",manual.queries==0&&manual.reads==1&&!matched(s,manual));manual.readBad.accept(new UnsupportedOperationException());s.pump();check("Only explicit legacy system may continue with unconfirmed native bridge",manualDone.equals(Arrays.asList(true))&&!matched(s,manual)&&!s.timeZone.status().optBoolean("nativeSettingReadback"));
    s=session();n=new Access(s.web.current);done=prepare(s,n);resolve(s,n,"UTC");bootstrap(s,n);s.context.vault.failPut=true;n.applyOk.accept(n.ack(n.applyToken,n.zone,n.context));s.pump();check("An unpersisted native ACK cannot claim a matched exit timezone",done.equals(Arrays.asList(false))&&!matched(s,n));
    s=session();s.privacy.level=2;n=new Access(s.web.current);done=prepare(s,n);check("Automatic IP under RFP resets native override without querying or weakening protection",done.isEmpty()&&n.queries==0&&n.reads==1&&s.privacy.level==2);accept(s,n);
    check("RFP priority permits protected browsing but never reports IP matching",done.equals(Arrays.asList(true))&&!matched(s,n)&&s.timeZone.allowed(n.nativeSession,n.epoch)&&s.timeZone.status().optBoolean("rfpPriority")&&s.timeZone.status().optString("effectiveMode").equals("rfp-priority")&&n.zone.isEmpty()&&s.privacy.level==2);
    JSONObject rfp=GeckoTimeZoneHost.rawObject(s.context).getJSONObject("receipt");check("RFP-priority reset receipt carries no fabricated IP observation",rfp.getBoolean("rfpManaged")&&rfp.opt("ipObservation")==JSONObject.NULL&&rfp.getString("effectiveZoneId").isEmpty()&&GeckoTimeZoneStore.load(s.context).spec.followsIp());
    s=session();n=new Access(s.web.current);done=prepare(s,n);s.privacy.level=2;n.queryOk.accept(envelope(n.queryToken,n.route,"8.8.8.8","America/New_York"));s.pump();check("A stronger protection change retires pending IANA resolution without applying it",done.equals(Arrays.asList(false))&&n.reads==0&&n.applies==0&&s.privacy.level==2);
    s=session();GeckoTimeZoneStore.save(s.context,s.timeZone.cached.identity,s.timeZone.cached.revision,GeckoTimeZoneSpec.of("America/New_York"));s.timeZone.refresh(null);s.pump();s.privacy.level=2;n=new Access(s.web.current);done=prepare(s,n);check("Manual IANA retains the original strict RFP conflict contract",done.equals(Arrays.asList(false))&&n.reads==0&&n.queries==0&&s.privacy.level==2&&s.timeZone.status().optString("state").equals("conflict"));
    s=session();n=new Access(s.web.current);done=prepare(s,n);resolve(s,n,"UTC");s.handler.advance(14999);s.pump();check("The original native fifteen-second deadline is preserved after IP resolution",done.isEmpty());s.handler.advance(1);s.pump();check("Native timeout still denies IP admission",done.equals(Arrays.asList(false))&&!matched(s,n));
  }
  static void ui()throws Exception{
    check("UI maps new default and explicit manual modes without ambiguity",GeckoTimeZoneUi.selectionFor(GeckoTimeZoneSpec.automatic())==0&&GeckoTimeZoneUi.selectionFor(GeckoTimeZoneSpec.system())==1&&GeckoTimeZoneUi.selectionFor(GeckoTimeZoneSpec.of("UTC"))==2&&GeckoTimeZoneUi.selectionFor(GeckoTimeZoneSpec.of("Asia/Kathmandu"))==3);
    check("Selecting system explicitly preserves manual choice even when IANA text remains",GeckoTimeZoneUi.selected(1,"Asia/Tokyo").followsSystem()&&GeckoTimeZoneUi.selected(0,"Asia/Tokyo").followsIp());rejects("Empty explicit IANA mode never silently becomes system",()->GeckoTimeZoneUi.selected(3,""));rejects("Unselected UI mode never silently becomes a timezone",()->GeckoTimeZoneUi.selected(-1,"UTC"));
    String pending=GeckoTimeZoneUi.summary(J.obj("loaded",true,"desiredMode","ip","desiredZone","","nativeSettingReadback",false,"ipMatched",false));check("Pending IP summary states unmatched and offers retry/manual choices",pending.contains("IP 时区未匹配")&&pending.contains("重试")&&pending.contains("手动")&&!pending.contains("已保存：跟随系统"));
    String matched=GeckoTimeZoneUi.summary(J.obj("loaded",true,"desiredMode","ip","desiredZone","","nativeSettingReadback",true,"ipMatched",true,"observedIp","8.8.8.8","effectiveZone","America/New_York"));check("Matched UI names observed IP/IANA while retaining Service Worker limitation",matched.contains("8.8.8.8")&&matched.contains("America/New_York")&&matched.contains("Service Worker 仍可读取系统时区")&&matched.contains("页面与 Worker 尚未验证"));
    String priority=GeckoTimeZoneUi.summary(J.obj("loaded",true,"desiredMode","ip","desiredZone","","nativeSettingReadback",true,"ipMatched",false,"rfpPriority",true));check("RFP summary separates desired IP from native standardized priority without requesting weaker privacy",priority.contains("统一时区优先")&&priority.contains("IP 匹配未生效")&&priority.contains("可继续")&&!priority.contains("重试"));
    String priorityPending=GeckoTimeZoneUi.summary(J.obj("loaded",true,"desiredMode","ip","desiredZone","","nativeSettingReadback",false,"ipMatched",false,"rfpPriority",true));check("RFP desired priority never claims current readiness before native acknowledgement",priorityPending.contains("尚待原生确认")&&priorityPending.contains("无需减弱保护")&&!priorityPending.contains("可继续"));
  }
  public static void main(String[] args)throws Exception{root=Paths.get(args[0]);Files.createDirectories(root);parser();specsAndStorage();sequenceAndRoute();failures();ui();System.out.println(J.obj("status","passed","passed",checks.size(),"total",checks.size(),"checks",new JSONArray(checks)));}
}

final class Access implements GeckoTimeZoneController.NativeAccess {
  final Object nativeSession;final String sid="native_session",epoch="native_epoch";boolean live=true;String route=IpTimeZoneHost.A,context="6",zone,queryToken,readToken,applyToken;int queries,reads,applies;
  Consumer<String> queryOk,readOk,applyOk;Consumer<Throwable> queryBad,readBad,applyBad;
  Access(Object value){nativeSession=value;}public boolean current(){return live;}public String ipRouteStamp(){return route;}
  public void lookupIp(String token,Consumer<String> ok,Consumer<Throwable> bad){queries++;queryToken=token;queryOk=ok;queryBad=bad;}
  public void read(String token,Consumer<String> ok,Consumer<Throwable> bad){reads++;readToken=token;readOk=ok;readBad=bad;}
  public void apply(String zone,String token,Consumer<String> ok,Consumer<Throwable> bad){applies++;this.zone=zone;applyToken=token;applyOk=ok;applyBad=bad;}
  String ack(String token,String zone,String context){return J.obj("schema",1,"status","applied","requestToken",token,"sessionId",sid,"requestedZoneId",zone,"nativeZoneId",zone,"contextId",context,"nativeSettingReadback",true,"scope","top-browsing-context","workerCoverageVerified",false,"serviceWorkerCoverageVerified",false).toString();}
}
final class QueueBoundary implements Executor {final ArrayDeque<Runnable> tasks=new ArrayDeque<>();public void execute(Runnable task){tasks.add(task);}void drain(){while(!tasks.isEmpty())tasks.remove().run();}}
final class HandlerBoundary {long now;final QueueBoundary immediate=new QueueBoundary();final TreeMap<Long,List<Runnable>> delayed=new TreeMap<>();void post(Runnable task){immediate.execute(task);}void postDelayed(Runnable task,long delay){if(delay!=8000&&delay!=15000)throw new AssertionError("Unexpected deadline");delayed.computeIfAbsent(now+delay,key->new ArrayList<>()).add(task);}void drain(){immediate.drain();}void advance(long elapsed){now+=elapsed;while(!delayed.isEmpty()&&delayed.firstKey()<=now)for(Runnable task:delayed.pollFirstEntry().getValue())task.run();}}
final class ChatSession {final TestContext context;final QueueBoundary environmentIo=new QueueBoundary();final HandlerBoundary handler=new HandlerBoundary();final GeckoWebView web=new GeckoWebView();final Privacy privacy=new Privacy();final EnvironmentAudit audit=new EnvironmentAudit();final GeckoTimeZoneController timeZone;String environmentId=GeckoTimeZoneHost.ID;int environmentGeneration=4;boolean deleted;ChatSession(TestContext context){this.context=context;timeZone=new GeckoTimeZoneController(this);}void pump(){for(int i=0;i<100&&(!environmentIo.tasks.isEmpty()||!handler.immediate.tasks.isEmpty());i++){environmentIo.drain();handler.drain();}if(!environmentIo.tasks.isEmpty()||!handler.immediate.tasks.isEmpty())throw new AssertionError("Unbounded writer queue");}void changed(){}void requestTaskGuardStatus(String reason,Consumer<Guard> done){done.accept(new Guard());}}
final class Guard {boolean known=true,replyBusy,fileBusy,submitting,downloading;}
final class Privacy {int level=1;int level(){return level;}}
final class GeckoWebView {static final String VERSION="host-native-boundary";Object current=new Object();int reloads;boolean hasVisibleDocument(){return false;}String getUrl(){return "";}void timezoneConfigurationChanged(){reloads++;}}
final class MainActivity {static boolean chatUrl(String url){return url.startsWith("https://chatgpt.com/");}}
final class EnvironmentAudit {int retired;void nativeDocumentProofChanged(Object object,String epoch){retired++;}}
